create table public.black_betty_planning_snapshot (
  singleton boolean primary key default true check (singleton),
  planning jsonb not null,
  version bigint not null default 1 check (version > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id),
  updated_by uuid references auth.users(id)
);

alter table public.black_betty_planning_snapshot enable row level security;

create or replace function private.set_black_betty_planning_snapshot_audit_fields()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.version = old.version + 1;
  new.updated_at = now();
  new.updated_by = (select auth.uid());
  return new;
end;
$$;

create trigger set_black_betty_planning_snapshot_audit_fields
before update on public.black_betty_planning_snapshot
for each row execute function private.set_black_betty_planning_snapshot_audit_fields();

revoke all on public.black_betty_planning_snapshot from anon;
revoke all on public.black_betty_planning_snapshot from authenticated;
grant select, update on public.black_betty_planning_snapshot to authenticated;

create policy "Black Betty users can view shared planning"
on public.black_betty_planning_snapshot
for select to authenticated
using (private.black_betty_role() in ('buyer', 'admin'));

create policy "Black Betty users can update shared planning"
on public.black_betty_planning_snapshot
for update to authenticated
using (private.black_betty_role() in ('buyer', 'admin'))
with check (private.black_betty_role() in ('buyer', 'admin'));

